FETCH_INSTANTID_PY = '#!/usr/bin/env python3\n"""\nFetch the InstantID diffusers pipeline and write a traceable header.\n\nInstantID is not part of diffusers core: it lives in\n`examples/community/pipeline_stable_diffusion_xl_instantid.py` in the diffusers\nrepo, and is *not* shipped inside the pip wheel. The previous runs died because\na hand-written import of something "not in core" was assumed to exist, so this\nbootstrapper is explicit about where the file comes from and fails loudly with a\nusable message instead of an ImportError deep inside a worker.\n\nOrder of attempts:\n  1. a vendored copy committed next to this script (`_vendor/`), if present\n  2. the same file from the diffusers tag matching the installed version\n  3. the diffusers `main` copy\n\nThe written module is imported as `instantid_pipeline`.\n"""\n\nfrom __future__ import annotations\n\nimport importlib.util\nimport sys\nimport urllib.error\nimport urllib.request\nfrom pathlib import Path\n\nVENDOR_DIR = Path(__file__).resolve().parent\nTARGET = VENDOR_DIR / "instantid_pipeline.py"\nCOMMITTED = VENDOR_DIR / "_vendor" / "pipeline_stable_diffusion_xl_instantid.py"\nMODULE_URL = (\n    "https://raw.githubusercontent.com/huggingface/diffusers/{ref}"\n    "/examples/community/pipeline_stable_diffusion_xl_instantid.py"\n)\n\n#: Upstream pins these; the file is a diffusers community pipeline and tracks\n#: the pipeline internals closely.\nREQUIRED_SYMBOLS = (\n    "class StableDiffusionXLInstantIDPipeline",\n    "def draw_kps",\n    "load_ip_adapter_instantid",\n)\n\n\ndef _version_tag() -> str:\n    try:\n        import diffusers\n\n        return f"v{diffusers.__version__}"\n    except Exception:\n        return "main"\n\n\ndef _download(url: str, timeout: int = 120) -> str:\n    with urllib.request.urlopen(url, timeout=timeout) as response:\n        return response.read().decode("utf-8")\n\n\ndef _with_header(source: str) -> str:\n    return (\n        "# Generated by scripts/luca_v2/fetch_instantid.py\\n"\n        "# Source: huggingface/diffusers examples/community/\\n"\n        "# pipeline_stable_diffusion_xl_instantid.py\\n"\n        "# Do not edit: re-run the bootstrapper instead.\\n"\n        + source\n    )\n\n\ndef _validate(source: str) -> None:\n    missing = [symbol for symbol in REQUIRED_SYMBOLS if symbol not in source]\n    if missing:\n        raise RuntimeError(\n            f"downloaded InstantID pipeline is missing {missing} — the upstream "\n            "file changed shape, so the call sites in generate_images.py need "\n            "reviewing before this can run"\n        )\n\n\ndef ensure_pipeline(force: bool = False) -> Path:\n    """\n    Materialise instantid_pipeline.py next to this file and return its path.\n\n    The committed copy under `_vendor/` is the primary source: a GPU run should\n    never depend on reaching raw.githubusercontent.com. Network fetch is only a\n    fallback for when the vendored file is absent or explicitly refreshed.\n    """\n    if not force and COMMITTED.is_file():\n        _validate(COMMITTED.read_text(encoding="utf-8"))\n        if not TARGET.is_file() or \\\n                TARGET.read_text(encoding="utf-8") != _with_header(COMMITTED.read_text(encoding="utf-8")):\n            TARGET.write_text(\n                _with_header(COMMITTED.read_text(encoding="utf-8")), encoding="utf-8")\n        print(f"[instantid] using committed vendored pipeline ({COMMITTED.name})",\n              flush=True)\n        return TARGET\n\n    if TARGET.is_file() and not force:\n        _validate(TARGET.read_text(encoding="utf-8"))\n        print(f"[instantid] using existing pipeline: {TARGET}", flush=True)\n        return TARGET\n\n    attempts = []\n    tag = _version_tag()\n    for ref in (tag, "main"):\n        url = MODULE_URL.format(ref=ref)\n        try:\n            print(f"[instantid] fetching pipeline from {ref}", flush=True)\n            source = _download(url)\n            _validate(source)\n            TARGET.write_text(_with_header(source), encoding="utf-8")\n            print(f"[instantid] wrote {TARGET} ({len(source) / 1024:.0f} KB) "\n                  f"from ref={ref}", flush=True)\n            return TARGET\n        except urllib.error.HTTPError as exc:\n            attempts.append(f"{ref}: HTTP {exc.code}")\n        except Exception as exc:\n            attempts.append(f"{ref}: {type(exc).__name__}: {exc}")\n        print(f"[instantid] ref={ref} failed: {attempts[-1]}", flush=True)\n\n    raise SystemExit(\n        "could not obtain the InstantID diffusers pipeline.\\n"\n        f"  target: {TARGET}\\n"\n        "  attempts:\\n    " + "\\n    ".join(attempts) + "\\n"\n        "  fix: vendor the file manually into "\n        f"{TARGET.parent} or re-run with network access."\n    )\n\n\ndef _import_check(path: Path) -> None:\n    """\n    Prove the pipeline *imports*, but only if its runtime deps are present.\n\n    The launcher runs this before either worker, i.e. before `pip install\n    opencv/diffusers`. Importing unconditionally would abort the whole run on\n    Kaggle with a bare ModuleNotFoundError for a dependency the worker is about\n    to install. The file\'s correctness is still checked by _validate(); the\n    import test is a bonus that only applies in a provisioned environment.\n    """\n    missing = [m for m in ("cv2", "diffusers", "insightface", "torch")\n               if importlib.util.find_spec(m) is None]\n    if missing:\n        print(f"[instantid] import check skipped — not installed yet: "\n              f"{\', \'.join(missing)} (the worker installs these)", flush=True)\n        return\n\n    sys.path.insert(0, str(path.parent))\n    import instantid_pipeline  # noqa: F401  (import check only)\n    print(f"[instantid] import OK: {instantid_pipeline.__file__}", flush=True)\n\n\nif __name__ == "__main__":\n    _path = ensure_pipeline(force="--force" in sys.argv)\n    _import_check(_path)\n'

